SELECT "p"."Id", "p"."Name", "p"."PersonType" FROM "Peoples" AS "p" WHERE EXISTS ( SELECT 1 FROM "BaseItems" AS "b" WHERE "b"."Type" = @personType AND "b"."Name" = "p"."Name") AND "p"."Id" IN ( SELECT MIN("p1"."Id") FROM ( SELECT "p0"."Id", lower("p0"."Name") AS "Key" FROM "Peoples" AS "p0" WHERE EXISTS ( SELECT 1 FROM "BaseItems" AS "b0" WHERE "b0"."Type" = @personType AND "b0"."Name" = "p0"."Name") ) AS "p1" GROUP BY "p1"."Key" ) ORDER BY lower("p"."Name") LIMIT @p
